insert into handbook_sections (slug, title, parent_slug, order_index, pull_quote, content, visibility, is_published) values
  ('preface', 'Preface', null, 1, 'The Forest is vast, but no Gnome walks it alone.', 'Congratulations, you''ve entered the Forest! Gn0me Home''s Staff Cadre is here to keep our community fun, fair, and a home for all Gnomes! This handbook is designed to help you understand our mission, explain your new duties, and ensure you have what you need to succeed!

We want your experience on Staff to be just as fun as when you were a Gn0me Child, and we never want this to feel too much like work. This clan is as much for the Trees as it is for anyone else, and your involvement will help us keep moving in the right direction. Thank you for being a Gnome!', 'clan_member', true),
  ('forest-explained', 'The Forest Explained', null, 2, 'Council, Yew, Pine, and Oak — different rings, same tree.', 'Our commitment within Gn0me Home''s Staff Cadre is to always work together as a team to achieve our goals. If we are ruling from the top, we''ve failed ourselves. While we do have ranks, they are meant to help identify someone''s role, and never to prevent you from taking charge or to stop your voice being heard. Here is a more detailed breakdown:

- **Gnome Council — Founding Members.** Also known as the "Hats", the Council helped to build Gn0me Home from a seed pod. The Council acts as a Board of Trustees to set the vision and make sure we are adhering to our core values. They may have similar roles and permissions to Yews (Senior Staff) but generally do not hold an active leadership role in our day-to-day operations. The Council can vote, enforce our rules, and take on an active leadership role if they desire.
- **Yew — Senior Staff.** While Yews may appear fewer in number, they stand tall in the forest and help shape the canopy. Yews serve as the highest active leadership role in Gn0me Home. They act in a similar fashion to a Chief Executive Officer to set strategy, hire and mentor members of staff, ensure that core clan functions are being executed, and represent the clan officially. If you have a concern or need guidance, seek a Yew for support.
- **Pine — Staff.** Pines are the lifeblood of the forest, providing shade and comfort for all Gnomes below. Where Yews are setting the tone, Pines are executing. A Pine''s main duties are to act as our Community Managers. They do this by welcoming and mentoring new clan members, engaging in the community through clan chat and Discord, hosting events, and by generally being a friendly face. We envision the majority of our Staff Cadre being Pines and view them as a shining example of what it means to be a Gnome.
- **Oak — Trial Staff.** Oaks are younger and newer to the forest, but also strong and never looked down upon. All members of Staff begin as an Oak. An Oak''s duties are similar to a Pine''s and should be a friendly and familiar face to all in our community. Engaging in the community, moderating actions, and hosting events are all the right things that you should be doing as an Oak to continue growing. In this role, if you need help, never feel bad about asking. And if you have an idea, never be afraid to pitch it. Without Oaks we couldn''t keep the forest growing.', 'clan_member', true),
  ('duties-expectations', 'Duties & Expectations', null, 3, 'Many hands make light work.', 'We want to make your time on staff enjoyable too! If we aren''t having fun, the rest of the clan won''t either. This list of duties is meant to be a guide for how to succeed as a member of Staff, and not as a list of chores to accomplish.

- **Follow and help to enforce Clan Rules.** This includes in-game and on Discord. Set a shining example for others to follow and call out bad behavior when it goes too far. If more action than just a verbal warning is needed, refer to [Handling Discipline Concerns](/staff-handbook/discipline). Remember, we''re all adults here, so we permit some foul language and dirty jokes, but never let it go too far or make others uncomfortable.
- **Foster a welcoming environment.** You''re on the frontlines for the clan, and staff members should be seen as friendly faces in our community. Set the tone by welcoming new members, helping them access the Website and Discord Server, and making sure they have what they need.
- **Stay engaged in the community.** This one should be self-explanatory — as best you can, please stay active in clan chat, post in Discord, attend events, and encourage others to join in on the fun!
- **Host events when able.** Events keep our community engaged. To ensure the weight of hosting doesn''t fall to one person, we ask everyone to volunteer to host when they''re able. There''s no quota or set schedule. Refer to [Events & Challenges](/staff-handbook/events-challenges).
- **Mentor when you can.** Gn0me Home has Grandmasters and noobs — be ready to help anyone on their journey, and if you don''t know, help them find the info they need! Refer to [Onboarding & Mentoring](/staff-handbook/onboarding-mentoring).
- **Stay active in Staff Channels.** We want your voice to be heard. Great ideas come from our diverse backgrounds and skillsets. Help us set the path, plan events, and vote on the way forward for the Clan!', 'clan_member', true),
  ('discipline', 'Handling Discipline Concerns', null, 4, 'Even in rain, the Forest holds its shape.', 'Hopefully nothing major arises, but if it does, we want you to be prepared to tackle it. In most cases, a simple verbal warning should suffice; however, sometimes it might not be enough, and this guide is here to help. Always consult the [Clan Rules](/staff-handbook/appendix-clan-rules) for reference and use the #discipline-log to record events when necessary. Remember, these issues can arise in-game and in the Discord, so please stay vigilant to keep Gn0me Home fun and fair for all!

You are a trusted member of our community. If someone comes to you with an issue about another clan member, talk them through their concerns privately and ask if they would like help resolving the issue. If you don''t feel comfortable being the one to resolve it, let us know in the Officer Chat. If you observe a serious offense, or are made aware of one, follow the guidelines below.

- **1. Breaking "Respect & Conduct".** Most lighthearted banter and dirty jokes are fine, we''re adults! But if it goes too far, is offensive, directed at someone, or is making clan members uncomfortable, it may be time to step in. A simple warning in chat should do, but if it continues: make a second warning, screenshot, and document in the Discipline Log. If the behavior crosses into hate speech, harassment, or doxxing, skip the warning steps entirely — document immediately and notify a Yew or Council member, same as a Zero Tolerance case below.
- **2. Breaking "In-game Conduct".** We have a Zero Tolerance policy for this. This covers things like real-world trading, botting/macroing, and account sharing or selling. If you suspect someone of this type of activity or have been alerted to it by a clan member: document immediately in the Discipline Log and notify a Yew or Council member right away. We will review and decide next steps.
- **3. Breaking "Discord Conduct".** If someone is spamming in the Discord, it might be best to DM them and ask them to stop. If they are posting in the wrong area, kindly reply and direct them to the right channel for future posts! If something NSFW or wildly inappropriate has been posted: immediately delete it and document in the Discipline Log. If you cannot delete the message, alert leadership ASAP.

A note on permissions: only Yews and Council members can mute, kick, or ban. If you''re an Oak or Pine, your job is to warn, document, and notify leadership — never take punitive action yourself, even if you''re sure.', 'clan_member', true),
  ('events-challenges', 'Events & Challenges', null, 5, 'Events and challenges keep the fun alive in Gn0me Home!', 'Events and challenges keep the fun alive in Gn0me Home! As a member of Staff, we ask that you help us to promote and run these activities to ensure we''re delivering on our promises. By now you''ll have seen that many of our events are part of a Weekly Series, and our challenges are up and running, but that doesn''t mean that we can''t change things up or add new and exciting ideas into the mix!

The next two sections are designed to help teach you what types of activities we have to offer, and how to go about planning and hosting them:

- [4a. Types of Activities](/staff-handbook/events-types)
- [4b. Posting & Hosting](/staff-handbook/events-posting-hosting)', 'clan_member', true),
  ('events-types', '4a. Types of Activities', 'events-challenges', 1, null, '## EVENTS

- **Large Events.** Drop Parties, Parades, Tournaments, Hide n'' Seek, the list goes on. These events are typically a whole-of-staff effort to put on and host. Generally hosted on the weekend to maximize participation. Anyone can suggest an idea, and we''ll work together to shape it!
- **Weekly Events.** Minigame Monday, Social Tuesday, PVM Thursday, Skilling Friday. These go on every week and for most occasions we vote on the activity in the Clan Hall at event time. If you''d like to plan ahead, you are more than welcome to pick and post an activity — [4b. Posting & Hosting](/staff-handbook/events-posting-hosting) will help you do so! PVM Thursday rotates weekly between Raiding and Bossing, with Bosses lining up with our Boss of the Week.
- **Other Events.** Just because we have our weekly events lined up doesn''t mean you can''t double up! Feel free to post and host events whenever works for you, doubling up on days or event types!

## CHALLENGES

- **Skill or Kill of the Week.** Skill of the Week or Boss of the Week. We rotate them weekly to keep things fresh. We''ve recently expanded our prize pool to make things more fun and started running two Boss challenges (Late game and Early game) to be more inclusive! Runs Sunday–Sunday starting and ending at 8PM ET.
- **Weekly Event Attendance Raffle.** Implemented to help increase event engagement. Each event attended gives an additional entry in the raffle. Event attendance is tracked on our website — please remind clan members to check in!
- **Monthly Bond Giveaway.** 1-2 OSRS Bonds (or cash equivalent) given out at the end of each month. Signups posted in #giveaways.
- **Community Challenges.** Anyone can post and host their own challenges in #community-challenges. Got a fun idea? Post it! Encourage and assist clan members to post their own here too!', 'clan_member', true),
  ('events-posting-hosting', '4b. Posting & Hosting', 'events-challenges', 2, null, '## POSTING

- Gather event details and determine if you want your event to be part of our Weekly Series or a standalone event. If it''s part of a Weekly Series, post it directly in the ongoing thread. Standalone events get their own threads.
- You can manually post or use the Admin Panel on the Website (recommended). If posting manually, check out the Event Templates Guide. If using the Website, navigate to the "Create Event" feature inside the Admin Panel. To post your event to a specific Weekly Series, such as Minigame Monday, copy the link to the thread and paste it into "Post To (optional)".
- If posting manually, create an Event on the Event Calendar at the top of the Discord Server that mirrors the information from your post. The Website will automatically create this Event Entry for you.
- Ahead of your event, preferably a few hours beforehand, post a reminder using the "Event Pings" role encouraging people to attend. Also note in your message that attendance will give an additional entry in the Weekly Event Attendance Raffle.
- After the event, post an Event Recap. This can be done manually or by using the Admin Panel on the Website. When using the website, please link to where you posted your initial event. Only select "Close the forum post after posting this recap" for standalone events.

## HOSTING

- At or right before event time, start gathering clan members to the meeting location. When applicable, join voice chat and encourage participants to join as well!
- If the event requires gear, ensure that everyone is set up correctly. Similarly, make sure to review all special mechanics if there are any, such as for a boss or minigame.
- Remind clan members to check in to the event on the website. Copy and paste the check-in link to the Discord if they are having trouble finding it.
- During the event, please take screenshots. These will be used for your Event Recap post.
- Continue to take charge during the event and assist others if needed.
- Thank everyone for attending and once again encourage them to check in if they haven''t yet.
- Post your Event Recap — see "Posting, Step 5" above for more details.', 'clan_member', true),
  ('onboarding-mentoring', 'Onboarding & Mentoring', null, 6, 'Oaks are younger and newer to the forest, but also strong and never looked down upon.', 'If you''re a member of Staff, there''s a good chance you have some wisdom to share! We have clan members in all stages of their OSRS adventure, from 20-year veterans to brand new noobs, and any of them can have a question at any time.

When new players join Gn0me Home, it''s important for someone from staff to reach out to make sure they are fully welcomed and integrated into our community. Building these bonds early will help to make gnomies for life. Here are a few ways to stay involved:

- **Welcome new members.** If you recruit a new member, or are online when they join, reach out to them! Let them know you''re a member of staff and ask them if they need any help. Point them toward the Website, which also has the Discord link.
- **Answer questions in chat.** If you have the answer, share it! If you don''t, point them towards a clan member who might have it, or look it up and learn together!
- **Lead boss events or raids.** This type of content can be intimidating, especially for newer players. Teaching complex mechanics and sharing gear setups is a great way to help others out!
- **Offer to coach in voice chat.** Is a clan member asking for help with solo content, like the Fight Caves? Have them stream in the Discord and offer to walk them through in real time! You can use the study room voice channel under the Grand Library tab as a private channel.
- **Post guides.** The Grand Library is our knowledge hub, and we encourage you to help us create guides to fill it out. Clan members may also post their questions in the library — please respond if you see it!
- **Follow up with new members.** A quick "how are you settling in?" message a few days after someone joins goes a long way. You don''t need a formal system — just don''t let new faces go quiet.', 'clan_member', true),
  ('promotion-growth', 'Promotion & Growth', null, 7, 'While Yews may appear fewer in number, they stand tall in the forest and help shape the canopy.', 'There''s no point system or checklist for promotion — we''re not about to make this feel like a job. That said, if you''re an Oak wondering what growth looks like, here''s generally what Yews and Council look for when considering someone for Pine:

- **Consistency.** Showing up and staying engaged over time matters more than any single big moment.
- **Sound judgment.** Especially in discipline situations — staying calm, fair, and following the guide in [Handling Discipline Concerns](/staff-handbook/discipline).
- **Community impact.** Mentoring, hosting, and generally being a face people are glad to see.

If you''re curious where you stand, just ask a Yew — we''d rather you ask than wonder. Pine to Yew is a bigger step and is outside the scope of this handbook.', 'clan_member', true),
  ('inactivity-stepping-down', 'Inactivity & Stepping Down', null, 8, 'Life outside the Forest comes first, always.', 'Life outside the Forest comes first, always. If you need to go quiet for a while or step back from Staff entirely, there''s no guilt and no drama — just let a Yew know so we can plan around it.

- **Taking a break.** A quick heads-up in the Officer Chat is all we need. Your rank isn''t at risk for taking care of yourself.
- **Stepping down.** If you decide Staff life isn''t for you anymore, that''s completely okay — tell a Yew and we''ll handle the transition smoothly. You''re still a Gnome either way.
- **Coming back.** If we haven''t heard from you in a while, we''ll transfer you to the Redwood (Retired Staff) role, and you''re always welcome back! We''re always happy to have Staff return.', 'clan_member', true),
  ('website', 'The Gn0me Home Website', null, 9, null, '*Still working on this section — check back soon!*', 'clan_member', true),
  ('appendix-clan-rules', 'Appendix A: Clan Rules', null, 10, 'A Home for Gnomes.', '## THE GNOME CODE

By joining the server, you''ve agreed to these. They''re short, they''re fair, and they exist so everyone has a good time.

- [Respect & Conduct](/staff-handbook/rules-respect-conduct)
- [In-Game Conduct](/staff-handbook/rules-ingame-conduct)
- [Discord Conduct](/staff-handbook/rules-discord-conduct)
- [Zero Tolerance — Fast-Tracked for Removal](/staff-handbook/rules-zero-tolerance)
- [Discipline Process](/staff-handbook/rules-discipline-process)

Last updated: July 2026. Questions? Ping a Tree or a Gnome Council member.', 'anonymous', true),
  ('rules-respect-conduct', 'Respect & Conduct', 'appendix-clan-rules', 1, null, '- Treat everyone with respect. Banter is part of the culture here — targeted disrespect, bullying, or harassment is not.
- Keep drama out of public channels. If you have an issue with someone, go to DMs first. If it escalates, contact an officer. Public airing of grievances helps nobody.
- No hate speech, slurs, or discriminatory language of any kind. Zero tolerance — no context makes it acceptable.
- No begging — for GP, items, carries, or handouts. Asking for help is completely fine. Pestering people repeatedly is not.', 'anonymous', true),
  ('rules-ingame-conduct', 'In-Game Conduct', 'appendix-clan-rules', 2, null, '- No scamming, luring, or deceptive trading — inside or outside the clan. This is an instant permanent removal.
- No botting, cheating, or real-world trading (RWT). Jagex''s rules are our rules.
- For all group PvM, the event host announces the loot split before the boss. Follow it — no renegotiating mid-trip.
- Don''t join end-game events (CoX, ToB) drastically under the recommended gear level. Ask an officer beforehand if you''re unsure — there''s no judgment in asking.', 'anonymous', true),
  ('rules-discord-conduct', 'Discord Conduct', 'appendix-clan-rules', 3, null, '- No spam, walls of caps, or mass-pinging members.
- No NSFW content of any kind, anywhere in this server.
- Casual swearing is fine — keep it contextual, never directed at a person.
- Post in the right channels. It keeps things easy to find and the mods sane.', 'anonymous', true),
  ('rules-zero-tolerance', 'Zero Tolerance — Fast-Tracked for Removal', 'appendix-clan-rules', 4, null, 'These skip the warning ladder — Oaks and Pines report immediately, and a Yew or Council member handles removal.

- Scamming
- Harassment or doxxing
- Hate speech or slurs
- Botting
- Real-world trading
- NSFW content', 'anonymous', true),
  ('rules-discipline-process', 'Discipline Process', 'appendix-clan-rules', 5, null, 'Rule violations are handled privately. The standard process is: warning → temporary mute or demotion → removal. Zero-tolerance violations skip straight to removal.

If you believe a rule has been applied unfairly, DM a Head Gnome directly.', 'anonymous', true)
on conflict (slug) do update set title = excluded.title, parent_slug = excluded.parent_slug, order_index = excluded.order_index, pull_quote = excluded.pull_quote, content = excluded.content, visibility = excluded.visibility;